Ce afișează programul de mai jos?

```
#include <iostream>
using namespace std;

int main() {
    int n = 52817, s = 0, p = 1;
    while (n > 0) {
        int c = n % 10;
        if (c % 2 == 0) s = s + c * p;
        else p = p * 10;
        n = n / 10;
    }
    cout << s;
    return 0;
}
```

