#include <iostream>
using namespace std;

int apeluri = 0;

int fib(int n) {
    apeluri++;
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
}

int main() {
    int r = fib(6);
    cout << r << ' ' << apeluri;
    return 0;
}
